import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { AsOf } from './as-of';
import { UserColumns } from './columns';
import { UserLocale } from './locale';

// Who is signed in and which sheet is active. Everything else in the app is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);
  private readonly asOf = inject(AsOf);
  private readonly userLocale = inject(UserLocale);
  private readonly userColumns = inject(UserColumns);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  // The active sheet's today (yyyy-mm-dd): every date decision and default date uses it.
  readonly sheetToday = signal<string | null>(null);
  // Whether the active sheet is archived: it stays visible and every change on it is refused.
  readonly sheetArchived = signal(false);
  // The number of the active sheet's last bulk settle batch, or null when there has been none.
  readonly sheetLastBatch = signal<number | null>(null);
  // Counts sheet loads, so a view re-reads the store even when the same id is loaded again.
  readonly loads = signal(0);
  // The date the screen shows the sheet as of, or null: while set, every figure is as the sheet stood at the end of
  // it, the date stands in for the sheet's today, and every change is refused.
  readonly sheetAsOf = this.asOf.date.asReadonly();

  async signIn(name: string): Promise<void> {
    const u = await firstValueFrom(this.http.post<{ name: string }>('/api/signin', { name }));
    await this.userLocale.load();
    await this.userColumns.load();
    this.user.set(u.name);
  }

  async loadSheet(id: string): Promise<void> {
    const s = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}`, null),
    );
    this.sheetId.set(s.id);
    this.sheetToday.set(s.today);
    this.sheetArchived.set(s.archived);
    this.sheetLastBatch.set(s.lastBatch);
    this.loads.update((n) => n + 1);
  }

  // Shows the sheet as of the date (null: as it stands now), re-read from the store.
  async setAsOf(date: string | null): Promise<void> {
    this.asOf.date.set(date);
    const id = this.sheetId();
    if (id) await this.loadSheet(id);
  }

  async setToday(today: string): Promise<void> {
    const id = this.sheetId();
    if (!id) return;
    const s = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }),
    );
    this.sheetToday.set(s.today);
  }

  // Clones the active sheet to another id, never used before.
  async cloneSheet(toSheetId: string): Promise<void> {
    const id = this.sheetId();
    if (!id) return;
    await firstValueFrom(this.http.post(`/api/sheets/${encodeURIComponent(id)}/clone`, { toSheetId }));
  }

  async archive(): Promise<void> {
    const id = this.sheetId();
    if (!id) return;
    const s = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null),
    );
    this.sheetArchived.set(s.archived);
  }
}

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
  lastBatch: number | null;
}

  protected async saveToday(e: Event): Promise<void> {
    e.preventDefault();
    this.todayError.set(null);
    const today = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.todayError.set('Enter a date as yyyy-mm-dd.');
      return;
    }
    try {
      await this.session.setToday(today);
    } catch {
      this.todayError.set('Could not change the date.');
      return;
    }
    // the plans' next dates follow the sheet's today
    const sheet = this.session.sheetId();
    if (sheet) await this.plans.load(sheet).catch(() => undefined);
  }

  protected async setAsOf(e: Event): Promise<void> {
    e.preventDefault();
    this.asOfError.set(null);
    const date = this.asOfInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.asOfError.set('Enter a date as yyyy-mm-dd.');
      return;
    }
    try {
      await this.session.setAsOf(date);
    } catch {
      this.asOfError.set('Could not show the sheet as of that date.');
    }
  }

  protected async clearAsOf(): Promise<void> {
    this.asOfError.set(null);
    try {
      await this.session.setAsOf(null);
    } catch {
      this.asOfError.set('Could not show the sheet as it stands.');
    }
  }

  protected async cloneSheet(e: Event): Promise<void> {
    e.preventDefault();
    );
    if (me === undefined) return null;
    return {
      dueTotal: this.dueBy().get(me.id) ?? 'n/a',
      overdueTotal: this.overdueTotalBy().get(me.id) ?? '0.00',
    };
  });

  constructor() {
    // The pools offer these people, and count a member retired, or held, as soon as they are.
    effect(() => {
      const list = this.people().map((p) => ({ id: p.id, name: p.name, retiredFrom: p.retiredFrom, holds: p.holds }));
      untracked(() => this.poolRoster.people.set(list));
    });
    // Re-read the people from the store each time a sheet is loaded.
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.people.set([]);
        this.claims.set([]);
        this.usedTags.set([]);
        this.statements.set([]);
        this.patrons.set([]);
        this.watched.set(new Set());
        this.patronChoices.set({});
        this.aliasInputs.set({});
        this.patronErrors.set({});
        this.mergeChoices.set({});
        this.transferTargets.set({});
        this.rowErrors.set({});
        this.retireDates.set({});
        this.inlineGrades.set({});
        this.statementAsOfs.set({});
        this.holdFroms.set({});
        this.holdTos.set({});
        this.reset();
        this.quickName.set('');
        this.quickAmount.set('');
        this.quickError.set(null);
        this.pasteText.set('');
        this.pasteAdded.set(null);
        this.pasteError.set(null);
        this.planStore.list.set([]);
        this.plansGenerated.set(null);
        this.planGenerateError.set(null);
        this.importText.set('');
        this.importAdded.set(null);
        this.importError.set(null);
        this.selectedPeople.set(new Set());
        this.bulkGrade.set('A');
        this.bulkGradeFrom.set('');
        this.bulkGraded.set(null);
        this.bulkGradeError.set(null);
        this.bulkRetireFrom.set('');
        this.bulkRetired.set(null);
        this.bulkRetireError.set(null);
        this.bulkReassignTo.set('');
        this.bulkReassigned.set(null);
        this.bulkReassignError.set(null);
        this.bulkRedateDate.set('');
        this.bulkRedated.set(null);
        this.bulkRedateError.set(null);
        if (id) void this.fetch(id);
      });
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement | HTMLSelectElement).value;
  }

  protected checked(e: Event): boolean {
    return (e.target as HTMLInputElement).checked;
  }

  protected setRetireDate(id: number, date: string): void {
    this.retireDates.update((d) => ({ ...d, [id]: date }));
    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
  }

